INSERT INTO public.questions (topic, language, role, difficulty, type, text, sample_answer, tags, source) VALUES
('basic','C','all','easy','coding','Write a C program to reverse a string in place without using library functions.','Approach: use two indices, one at the start and one at the end, swap characters and move inward until they meet. Time O(n), space O(1). Code: void rev(char *s){int i=0,j=strlen(s)-1;while(i<j){char t=s[i];s[i++]=s[j];s[j--]=t;}}','["strings","two-pointers"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','C','all','easy','coding','Write a C function to compute the factorial of n both iteratively and recursively. Discuss overflow.','Approach: iterative loop multiplying 1..n into an unsigned long long; recursive version returns n*fact(n-1) with base case 1. Factorial overflows 64-bit past n=20, so validate input. Code: unsigned long long fact(int n){unsigned long long r=1;for(int i=2;i<=n;i++)r*=i;return r;}','["math","recursion"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','C','all','easy','coding','Write a C program that prints the first n Fibonacci numbers using O(1) extra space.','Approach: keep two running values a=0,b=1, print a then shift the pair. Time O(n), space O(1). Code: void fib(int n){long a=0,b=1;for(int i=0;i<n;i++){printf("%ld ",a);long t=a+b;a=b;b=t;}}','["math","iteration"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','C','all','easy','coding','Check whether an integer is a palindrome in C without converting it to a string.','Approach: reverse half the digits using modulo and division, compare with the remaining half. Negative numbers are not palindromes. Time O(log n), space O(1). Code: int isPal(int x){if(x<0)return 0;long r=0,t=x;while(t){r=r*10+t%10;t/=10;}return r==x;}','["math","numbers"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','C','all','easy','coding','Swap two integers in C without using a temporary variable, and explain when the trick fails.','Approach: use arithmetic a=a+b; b=a-b; a=a-b; or XOR. The XOR trick fails when both pointers reference the same address, since the value zeroes out. Prefer a temp variable in production code for clarity.','["bit-manipulation","basics"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','C','all','easy','coding','Find the largest and second largest element in an integer array in a single pass in C.','Approach: track first and second maxima while scanning once; update second only when the value is smaller than first but larger than second. Time O(n), space O(1). Handle arrays with fewer than two distinct values explicitly.','["arrays","scanning"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','C','all','easy','coding','Count vowels, consonants and digits in a string using C.','Approach: iterate once over the string, lowercase each character, and increment counters based on membership tests. Time O(n), space O(1). Use isalpha and isdigit from ctype.h to keep the checks readable.','["strings","counting"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','C','all','medium','coding','Implement bubble sort in C with the early-exit optimisation and state its complexity.','Approach: repeated adjacent swaps; keep a swapped flag so a sorted pass ends the algorithm early. Best case O(n) when already sorted, worst and average O(n^2), space O(1). It is stable but unsuitable for large inputs.','["sorting","arrays"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','CPP','all','easy','coding','Reverse a std::string in C++ in place, and mention the standard-library alternative.','Approach: two-pointer swap from both ends, O(n) time and O(1) space. The standard alternative is std::reverse(s.begin(), s.end()), which does the same thing and is preferred in real code.','["strings","stl"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','CPP','all','easy','coding','Remove duplicate characters from a string in C++ while preserving order.','Approach: keep a boolean array of 256 seen flags or an unordered_set, append each unseen character to the result. Time O(n), space O(1) for a fixed alphabet. Code: string dedup(const string &s){bool seen[256]={};string r;for(char c:s)if(!seen[(unsigned char)c]){seen[(unsigned char)c]=true;r+=c;}return r;}','["strings","hashing"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','CPP','all','easy','coding','Given a vector of integers, return the frequency of every element using C++ STL.','Approach: use unordered_map<int,int> and increment per element in one pass, then print pairs. Time O(n) average, space O(k) for k distinct values. Use std::map when sorted output is required.','["stl","hashing"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','CPP','all','easy','coding','Write a C++ function to check whether two strings are anagrams.','Approach: if lengths differ return false; count characters in a 26-element array for the first string, decrement for the second, and verify all counts are zero. Time O(n), space O(1). Sorting both strings is an O(n log n) alternative.','["strings","counting"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','CPP','all','medium','coding','Explain and implement a shallow copy versus a deep copy for a C++ class holding a raw pointer.','Approach: the default copy constructor copies the pointer value, so two objects free the same memory - a double delete. A deep copy allocates new storage and copies the contents. Follow the rule of three or five, or hold the resource in std::unique_ptr and let the compiler handle it.','["oop","memory"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','CPP','all','easy','coding','Compute the sum of digits of a number in C++ and return the digital root.','Approach: repeatedly take n%10 and divide by 10 to accumulate the digit sum; loop again until the result is a single digit for the digital root. Time O(log n), space O(1). The closed form is 1 + (n - 1) % 9 for n > 0.','["math","numbers"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','CPP','all','medium','coding','Implement binary search in C++ on a sorted vector and explain the overflow-safe midpoint.','Approach: maintain lo and hi, compute mid = lo + (hi - lo) / 2 to avoid integer overflow, shrink the range each step. Time O(log n), space O(1). Return -1 when the value is absent.','["searching","arrays"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','CPP','all','easy','coding','Print a Pascal triangle of n rows in C++.','Approach: each row starts and ends with 1 and every inner value is the sum of the two values above it; build row i from row i-1 in a vector. Time O(n^2), space O(n) if only the previous row is kept.','["arrays","math"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','PYTHON','all','easy','coding','Reverse a string in Python three different ways and compare them.','Approach: slicing s[::-1] is the idiomatic and fastest option; "".join(reversed(s)) is equally clear; a manual loop is O(n) but slower because strings are immutable and concatenation copies. All are O(n) time and O(n) space.','["strings","pythonic"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','PYTHON','all','easy','coding','Write a Python function that returns the most frequent element in a list.','Approach: use collections.Counter(nums).most_common(1)[0][0], or build a dict manually in one pass. Time O(n), space O(k). Decide explicitly how ties should break, since Counter returns insertion order among ties.','["dict","counting"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','PYTHON','all','easy','coding','Explain the difference between a list, a tuple and a set in Python with a small code example.','Approach: lists are mutable ordered sequences, tuples are immutable and hashable so they can be dict keys, sets are unordered collections of unique hashable items with O(1) membership tests. Choose a set when you only need membership and uniqueness.','["data-types","basics"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','PYTHON','all','medium','coding','Write a Python decorator that measures and prints the execution time of any function.','Approach: wrap the function with functools.wraps, record time.perf_counter before and after the call, print the delta and return the result. Code: def timed(fn):\n  @wraps(fn)\n  def w(*a, **k):\n    t=perf_counter(); r=fn(*a,**k); print(perf_counter()-t); return r\n  return w','["decorators","functions"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','PYTHON','all','easy','coding','Given two lists, return their intersection without duplicates in Python.','Approach: convert both to sets and use the & operator, returning list(set(a) & set(b)). Time O(n+m), space O(n+m). If ordering matters, filter the first list against a set built from the second.','["sets","lists"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','PYTHON','all','medium','coding','Explain mutable default arguments in Python and how to fix the common bug.','Approach: default values are evaluated once at function definition, so a default list is shared between calls and accumulates values. Fix it by defaulting to None and creating a fresh list inside the function body.','["gotchas","functions"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','PYTHON','all','easy','coding','Write a Python generator that yields prime numbers up to n and explain why a generator is useful here.','Approach: use a sieve of Eratosthenes to mark composites, then yield the remaining indices. A generator streams results lazily so memory stays bounded for the consumer, though the sieve itself is O(n) space. Time O(n log log n).','["generators","math"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','PYTHON','all','easy','coding','Count word frequency in a paragraph in Python, ignoring case and punctuation.','Approach: lowercase the text, strip punctuation with str.translate or a regex, split on whitespace, and count with collections.Counter. Time O(n), space O(k) distinct words. Mention stop-word removal as a follow-up.','["strings","counting"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','JAVA','all','easy','coding','Reverse a string in Java and explain why String is immutable.','Approach: new StringBuilder(s).reverse().toString() is the standard answer. String is immutable so instances can be safely shared, cached in the string pool, and used as hash keys; every modification creates a new object.','["strings","immutability"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','JAVA','all','easy','coding','Explain the difference between == and equals() in Java with an example.','Approach: == compares references for objects and values for primitives, while equals compares logical content and can be overridden. Two Strings built at runtime can be equal but not ==, which is why equals must be used for content comparison, along with a consistent hashCode.','["oop","basics"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','JAVA','all','easy','coding','Find duplicate elements in an int array in Java.','Approach: insert each element into a HashSet and report values whose add returns false. Time O(n), space O(n). Sorting first is an O(n log n) alternative that uses O(1) extra space.','["arrays","collections"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','JAVA','all','medium','coding','Explain the difference between ArrayList and LinkedList in Java and when to pick each.','Approach: ArrayList is backed by a resizable array with O(1) random access and amortised O(1) append but O(n) middle insertion; LinkedList is a doubly linked list with O(1) insertion given a node reference but O(n) indexing and worse cache locality. Prefer ArrayList unless you insert or remove at the ends heavily.','["collections","complexity"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','JAVA','all','easy','coding','Write a Java method to check whether a number is an Armstrong number.','Approach: count the digits d, then sum each digit raised to the power d and compare with the original. Time O(log n), space O(1). Example: 153 = 1^3 + 5^3 + 3^3.','["math","numbers"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','JAVA','all','medium','coding','Explain checked versus unchecked exceptions in Java and demonstrate try-with-resources.','Approach: checked exceptions extend Exception and must be declared or handled; unchecked exceptions extend RuntimeException and signal programming errors. try-with-resources auto-closes anything implementing AutoCloseable, which removes leaky finally blocks.','["exceptions","basics"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','JAVA','all','easy','coding','Sort a list of objects in Java by a field using Comparator and streams.','Approach: list.sort(Comparator.comparing(Person::getAge)) or the stream form sorted(...).collect(toList()). Comparable defines the natural order inside the class, Comparator defines an external order. Time O(n log n).','["collections","streams"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('basic','JAVA','all','medium','coding','Explain the Java memory model briefly: stack versus heap and garbage collection.','Approach: local primitives and references live on the per-thread stack, objects live on the shared heap. The garbage collector reclaims unreachable heap objects, typically using generational collection with young and old regions. Memory leaks in Java come from unintended strong references, not missing frees.','["jvm","memory"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','easy','theory','Explain how you would find the maximum subarray sum in an array, and give the complexity.','Kadane algorithm scans the array once keeping the best sum ending at the current index and the best sum seen overall. At each element you choose between extending the previous subarray or starting fresh. Time O(n) and space O(1). Handle the all-negative case by initialising with the first element rather than zero.','["array","kadane"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','medium','theory','Given a sorted array, how do you find a pair that sums to a target? Compare with the hashing approach.','Use two pointers from both ends: move left forward when the sum is too small and right backward when it is too large. Time O(n), space O(1) and it needs sorted input. Hashing works on unsorted arrays in O(n) time but uses O(n) space, so pick based on whether sorting or memory is cheaper.','["array","two-pointers"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','easy','theory','How would you check whether a string of brackets is balanced, and why is a stack the right structure?','Push every opening bracket and pop on a closing bracket, verifying the popped type matches. The string is balanced only if every pop matches and the stack is empty at the end. A stack is right because bracket nesting is last-in first-out. Time O(n), space O(n).','["stack","strings"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','medium','theory','Design a stack that returns the minimum element in O(1) time.','Keep a second stack of running minima, pushing the smaller of the new value and the current minimum on every push, and popping both stacks together. Every operation stays O(1) and space is O(n). An alternative encodes the previous minimum in the stored value to save space.','["stack","design"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','medium','theory','How do you implement a queue using two stacks, and what is the amortised complexity?','Push into an input stack; when dequeuing, if the output stack is empty pour everything from input into output, reversing the order, then pop. Each element moves at most twice, so enqueue and dequeue are amortised O(1) even though a single dequeue may cost O(n).','["queue","stack"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','medium','theory','Explain a circular queue and why it is preferred over a linear array queue.','A circular queue wraps the rear index back to the start using modulo arithmetic, so slots freed by dequeues are reused instead of wasted. It keeps enqueue and dequeue at O(1) with a fixed O(n) buffer. Distinguish full from empty using a size counter or by leaving one slot unused.','["queue","design"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','easy','theory','How do you detect a cycle in a singly linked list, and how do you find where the cycle starts?','Floyd cycle detection moves a slow pointer one step and a fast pointer two steps; they meet inside the cycle if one exists. To find the entry point, reset one pointer to the head and advance both one step at a time until they meet again. Time O(n), space O(1).','["linkedlist","two-pointers"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','medium','theory','Describe how to reverse a singly linked list iteratively and recursively.','Iteratively keep prev, curr and next pointers, redirecting curr.next to prev while walking forward; return prev as the new head. Time O(n), space O(1). The recursive version reverses the rest of the list then flips the current link, but uses O(n) stack space.','["linkedlist","pointers"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','easy','theory','Compare the three depth-first traversals of a binary tree and name a use case for each.','Inorder visits left, node, right and yields sorted order in a binary search tree. Preorder visits the node first and is used to serialise or copy a tree. Postorder visits children before the node and is used to free memory or evaluate expression trees. All are O(n) time and O(h) space.','["tree","traversal"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','medium','theory','How do you find the lowest common ancestor of two nodes in a binary search tree?','Walk down from the root: if both values are smaller go left, if both are larger go right, otherwise the current node is the split point and therefore the lowest common ancestor. Time O(h), space O(1) iteratively. In a plain binary tree you instead recurse and return the node where the two searches diverge.','["tree","bst"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','medium','theory','Compare BFS and DFS on a graph: implementation, complexity and when to choose each.','BFS uses a queue and explores level by level, giving shortest paths in unweighted graphs; DFS uses a stack or recursion and dives deep, which suits cycle detection, topological sorting and connectivity. Both are O(V+E) time; BFS space is the widest frontier while DFS space is the deepest path.','["graph","traversal"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dsa','none','all','hard','theory','How do you detect a cycle in a directed graph, and how does it differ from the undirected case?','For directed graphs run DFS with three colours or a recursion-stack flag; an edge back to a node currently on the stack is a cycle. Undirected graphs only need a visited set plus the parent check, or a disjoint-set union that reports an edge joining two nodes already in the same component. Both are O(V+E).','["graph","cycles"]','Curated from public interview lists (LeetCode, GeeksforGeeks, CodeChef discussions)'),
('dbms','none','all','easy','theory','Explain normalisation and walk through 1NF, 2NF and 3NF.','1NF requires atomic column values with no repeating groups. 2NF additionally removes partial dependencies on part of a composite key. 3NF removes transitive dependencies so non-key columns depend only on the key. Normalising reduces redundancy and update anomalies, but heavy read workloads often denormalise deliberately for speed.','["normalization"]','Curated from public interview lists (GeeksforGeeks, PostgreSQL and MySQL official documentation)'),
('dbms','none','all','medium','theory','What is an index, how does a B-tree index work, and when does an index hurt performance?','An index is an auxiliary structure mapping column values to row locations; a B-tree keeps sorted keys in a balanced multi-way tree giving O(log n) lookups and efficient range scans. Indexes slow down inserts, updates and deletes because they must be maintained, and they consume storage, so index selectively based on real query patterns.','["indexing","performance"]','Curated from public interview lists (GeeksforGeeks, PostgreSQL and MySQL official documentation)'),
('dbms','none','all','easy','theory','Explain the ACID properties of a transaction with a concrete example.','Atomicity means all statements commit or none do, so a funds transfer never debits without crediting. Consistency means constraints hold before and after. Isolation means concurrent transactions do not observe each other partially. Durability means a committed result survives a crash, usually via a write-ahead log.','["transactions","acid"]','Curated from public interview lists (GeeksforGeeks, PostgreSQL and MySQL official documentation)'),
('dbms','none','all','medium','theory','Describe the SQL isolation levels and the anomalies each one prevents.','Read uncommitted allows dirty reads; read committed prevents dirty reads but allows non-repeatable reads; repeatable read prevents those but can allow phantom rows; serialisable prevents all three by making execution equivalent to some serial order. Higher isolation costs concurrency, so choose the weakest level that is correct for the workload.','["transactions","isolation"]','Curated from public interview lists (GeeksforGeeks, PostgreSQL and MySQL official documentation)'),
('dbms','none','all','easy','theory','Explain the different SQL joins and give an example of when you would use a LEFT JOIN.','INNER JOIN keeps only matching rows, LEFT JOIN keeps every row of the left table with nulls where no match exists, RIGHT JOIN is the mirror, and FULL OUTER JOIN keeps unmatched rows from both. A LEFT JOIN suits reports such as all customers with their orders, where customers with zero orders must still appear.','["sql","joins"]','Curated from public interview lists (GeeksforGeeks, PostgreSQL and MySQL official documentation)'),
('dbms','none','all','medium','theory','Write and explain a SQL query that returns the second highest salary from an employees table.','Use SELECT MAX(salary) FROM employees WHERE salary < (SELECT MAX(salary) FROM employees), which returns null when no such value exists. A window-function version uses DENSE_RANK() OVER (ORDER BY salary DESC) and filters rank = 2, which also handles ties explicitly. Prefer the window version on modern engines.','["sql","queries"]','Curated from public interview lists (GeeksforGeeks, PostgreSQL and MySQL official documentation)'),
('dbms','none','all','medium','theory','Compare SQL and NoSQL databases and describe when you would choose each.','Relational databases give a fixed schema, joins, and strong transactional guarantees, which fits financial and highly related data. NoSQL stores trade joins and sometimes strict consistency for flexible schemas and horizontal scale, which suits document, key-value, time-series or very high write volume workloads. The decision is driven by access patterns and consistency needs, not popularity.','["nosql","architecture"]','Curated from public interview lists (GeeksforGeeks, PostgreSQL and MySQL official documentation)'),
('dbms','none','all','easy','theory','Explain the ER model and how entities, attributes and relationships map to tables.','An entity becomes a table, attributes become columns and the primary key identifies rows. A one-to-many relationship becomes a foreign key on the many side, while a many-to-many relationship requires a junction table holding both keys. Weak entities depend on an owner and include the owner key in their identifier.','["er-model","design"]','Curated from public interview lists (GeeksforGeeks, PostgreSQL and MySQL official documentation)'),
('dbms','none','all','hard','theory','Explain database locking, the difference between shared and exclusive locks, and how deadlocks are handled.','Shared locks allow concurrent reads while exclusive locks block all other access to the resource. Deadlocks occur when transactions wait on locks held by each other; databases usually detect a cycle in the wait-for graph and abort the cheapest victim. Reducing lock scope and touching rows in a consistent order lowers the deadlock rate.','["locking","concurrency"]','Curated from public interview lists (GeeksforGeeks, PostgreSQL and MySQL official documentation)'),
('dbms','none','all','hard','theory','How would you diagnose and optimise a slow SQL query?','Start with EXPLAIN or EXPLAIN ANALYZE to read the plan and find sequential scans, bad join orders or row-estimate errors. Then add or fix indexes, rewrite correlated subqueries as joins, select only needed columns, and make sure statistics are current. Measure again after each change rather than applying optimisations blindly.','["performance","optimization"]','Curated from public interview lists (GeeksforGeeks, PostgreSQL and MySQL official documentation)'),
('os','none','all','easy','theory','Explain the difference between a process and a thread.','A process is an independent execution unit with its own address space, file descriptors and resources, while threads live inside a process and share its memory and resources but keep separate stacks and registers. Threads are cheaper to create and switch, but sharing memory means data races must be handled with synchronisation. A crash in one thread can take the whole process down.','["process","threads"]','Curated from public interview lists (GeeksforGeeks, Operating System Concepts by Silberschatz)'),
('os','none','all','medium','theory','Compare CPU scheduling algorithms: FCFS, SJF, Round Robin and priority scheduling.','FCFS is simple but suffers convoy effects; SJF minimises average waiting time but needs burst-length knowledge and can starve long jobs; Round Robin gives fair time slices and good response time for interactive systems, with the quantum controlling the context-switch overhead; priority scheduling serves important jobs first and needs ageing to avoid starvation.','["scheduling"]','Curated from public interview lists (GeeksforGeeks, Operating System Concepts by Silberschatz)'),
('os','none','all','medium','theory','State the four necessary conditions for deadlock and describe how each can be prevented.','Deadlock requires mutual exclusion, hold and wait, no preemption and circular wait. Prevention breaks one condition: allocate all resources at once, allow preemption, or impose a global ordering on resource acquisition to remove cycles. Alternatives are avoidance with the banker algorithm, or detection followed by recovery.','["deadlock"]','Curated from public interview lists (GeeksforGeeks, Operating System Concepts by Silberschatz)'),
('os','none','all','medium','theory','Explain virtual memory and how paging translates addresses.','Virtual memory gives each process a private linear address space larger than physical RAM by keeping inactive pages on disk. The MMU splits an address into a page number and offset, looks the page number up in the page table, and forms the physical address; the TLB caches recent translations. A missing page raises a page fault and the OS loads it from backing store.','["memory","paging"]','Curated from public interview lists (GeeksforGeeks, Operating System Concepts by Silberschatz)'),
('os','none','all','medium','theory','Compare page replacement algorithms FIFO, LRU and Optimal, and explain Belady anomaly.','FIFO evicts the oldest page and can show Belady anomaly, where more frames cause more faults. LRU evicts the least recently used page and approximates locality well, typically implemented with a clock or ageing bits. Optimal evicts the page used furthest in the future and is only a theoretical benchmark.','["memory","replacement"]','Curated from public interview lists (GeeksforGeeks, Operating System Concepts by Silberschatz)'),
('os','none','all','medium','theory','What is a race condition, and how do mutexes and semaphores prevent it?','A race condition occurs when the result depends on the unpredictable interleaving of threads touching shared state. A mutex enforces mutual exclusion with a single owner over a critical section, while a counting semaphore permits up to n concurrent holders and is also used for signalling. Both must be paired correctly and acquired in a consistent order to avoid deadlock.','["synchronization"]','Curated from public interview lists (GeeksforGeeks, Operating System Concepts by Silberschatz)'),
('os','none','all','easy','theory','Describe how a file system stores files: inodes, directories and allocation strategies.','An inode holds file metadata and pointers to data blocks, while a directory maps names to inode numbers, which is why hard links are cheap. Contiguous allocation is fast but fragments, linked allocation avoids fragmentation but is slow for random access, and indexed allocation with multi-level blocks is the common compromise. Journaling records intended changes so a crash leaves the file system recoverable.','["filesystem"]','Curated from public interview lists (GeeksforGeeks, Operating System Concepts by Silberschatz)'),
('os','none','all','medium','theory','List the main inter-process communication mechanisms and their trade-offs.','Pipes and FIFOs are simple byte streams between related or named endpoints; message queues preserve message boundaries; shared memory is the fastest but needs explicit synchronisation; sockets work across machines at higher cost. Choose based on whether the parties are related, how much data moves, and whether the communication crosses hosts.','["ipc"]','Curated from public interview lists (GeeksforGeeks, Operating System Concepts by Silberschatz)'),
('os','none','all','hard','theory','Explain virtualisation and how containers differ from virtual machines.','A hypervisor virtualises hardware so each virtual machine runs a full guest kernel, giving strong isolation at the cost of memory and boot time. Containers virtualise the operating system instead, sharing the host kernel through namespaces and cgroups, so they start in milliseconds and pack densely. Containers therefore trade some isolation for efficiency.','["virtualization"]','Curated from public interview lists (GeeksforGeeks, Operating System Concepts by Silberschatz)'),
('os','none','all','easy','theory','What is a system call, and what happens during a context switch?','A system call is the controlled entry point from user mode into kernel mode, trapping into the kernel to request privileged services such as file or network access. A context switch saves the current registers, program counter and memory mapping, then restores another task, which costs time and pollutes the CPU caches and TLB. Excessive switching therefore reduces throughput.','["syscalls","context-switch"]','Curated from public interview lists (GeeksforGeeks, Operating System Concepts by Silberschatz)');